// Hides unselected modification items from the Tulpa sheet.
// Run once per session (or on world load). Safe to re-run.

const HOOK_FLAG = "tulpaSheetFilterHookId";

// Remove any previously registered copy first
if (window[HOOK_FLAG]) {
  Hooks.off("renderNPCActorSheet", window[HOOK_FLAG]);
}

window[HOOK_FLAG] = Hooks.on("renderNPCActorSheet", (app, html, _context) => {
  const actor = app.document ?? app.actor;
  if (!actor?.flags?.["manifest-tulpa"]) return; // Not a Tulpa actor

  // html is an Element in ApplicationV2 (V13), fall back for V1
  const root = html instanceof Element ? html : html[0];
  if (!root) return;

  for (const el of root.querySelectorAll("[data-item-id]")) {
    const item = actor.items.get(el.dataset.itemId);
    if (!item) continue;

    const flags = item.flags?.["manifest-tulpa"] ?? {};
    // Hide if it's a mod-tracked item and not yet enabled
    if ("modEnabled" in flags && flags.modEnabled !== true) {
      el.style.display = "none";
    }
  }
});

ui.notifications.info("Tulpa sheet filter active.");
